/* Teacher reads the same private submissions that Game Studio writes. */
const G8Submissions=(()=>{
 let records={},loaded=new Set(),loading=new Map(),feedbackDrafts={};
 const ids={g8Game_platformer:[1,2],g8Game_traffic:[3],g8Game_nonogram:[4],g8Game_dungeon:[5],g8Game_wall:[6]};
 const titles={1:'Mulai dunia game',2:'Platformer',3:'Traffic Looper',4:'Nonogram',5:'Dungeon Battle',6:'Wall Jumper',7:'Game pilihan · modifikasi',8:'Game pilihan · demo'};
 const esc=s=>escHtml(String(s??''));
 function sources(assessment){return [...(ids[assessment]||[]),7,8];}
 function version(studentId,assessment){return sources(assessment).map(id=>id+':'+(records[studentId]?.student?.lessons?.[id]?.submission?.version||0)).join('|');}
 function snapshot(studentId,assessment){return Object.fromEntries(sources(assessment).flatMap(id=>{const sub=records[studentId]?.student?.lessons?.[id]?.submission;return sub?[[id,JSON.parse(JSON.stringify(sub))]]:[];}));}
 function isStaleRecord(record,id){return Object.keys(ids).some(key=>record.reviewed?.[key]===true&&record.evidenceVersions?.[key]!==undefined&&record.evidenceVersions[key]!==version(id,key));}
 function invalidateStale(){if(typeof dcTeacherState==='undefined'||dcTeacherState.grade!==8||dcTeacherState.quarter!==2)return;const draft=dcTeacherState.draft;let changed=false;for(const key of Object.keys(ids)){const previous=draft.evidenceVersions?.[key],hasSubmission=Object.keys(snapshot(dcTeacherState.studentId,key)).length>0;if(draft.reviewed?.[key]===true&&((previous!==undefined&&previous!==version(dcTeacherState.studentId,key))||(previous===undefined&&hasSubmission))){draft.reviewed[key]=false;changed=true;}}if(changed){dcTeacherState.dirty=true;renderDcAssessmentPanel();showAlert('Ada kiriman BSD baru. Periksa lagi proyek yang berubah; nilai yang tersimpan sebelumnya tetap tersedia.','warning');}}
 async function load(id,force=false){if(!id||typeof db==='undefined')return;if(loading.has(id))return loading.get(id);if(loaded.has(id)&&!force)return;const job=db.ref('learningProgress').child(id).child('grade8Games').once('value').then(s=>{records[id]=s.val()||{};loaded.add(id);invalidateStale();render();}).finally(()=>loading.delete(id));loading.set(id,job);return job;}
 async function refreshBeforeSave(id){await load(id,true);invalidateStale();}
 function proof(row){const url=g8EvidenceUrl(row?.projectUrl);return (url?'<p><a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">Buka karya siswa ↗</a></p>':'')+'<p class="g11-evidence-text"><b>Perubahan / bukti:</b> '+esc(row?.evidence||'—')+'</p><p class="g11-evidence-text"><b>Hasil uji / refleksi:</b> '+esc(row?.reflection||'—')+'</p>';}
 function card(studentId,id,open=false){const row=records[studentId]?.student?.lessons?.[id];if(!row)return '';const sub=row.submission,review=records[studentId]?.teacher?.reviews?.[id],draft=feedbackDrafts[studentId+'/'+id]||review||{},current=review?.sourceVersion===sub?.version;
  return '<details class="g11-evidence" '+(open?'open':'')+'><summary>Pertemuan '+id+' · '+esc(titles[id])+' · '+(sub?'Terkirim v'+sub.version:'Draft online · belum diajukan')+'</summary>'+(sub?'<small>Diterima Firebase: '+esc(new Date(sub.submittedAt).toLocaleString('id-ID',{timeZone:'Asia/Bangkok'}))+'</small>':'<p>Catatan ini sudah tersimpan online. Siswa belum menekan Kirim tugas.</p>')+proof(sub||row)+(sub&&['projectUrl','evidence','reflection'].some(k=>String(row[k]||'')!==String(sub[k]||''))?'<details><summary>Draft lebih baru · belum diajukan</summary>'+proof(row)+'</details>':'')+(sub?'<label>Feedback guru<textarea maxlength="2000" id="g8-feedback-'+id+'">'+esc(draft.message||'')+'</textarea></label><label>Status feedback<select id="g8-feedback-status-'+id+'"><option value="seen">Sudah dilihat</option><option value="needs_revision" '+(draft.status==='needs_revision'?'selected':'')+'>Perlu revisi</option><option value="accepted" '+(draft.status==='accepted'?'selected':'')+'>Diterima</option></select></label>'+(review&&!current?'<small>Feedback sebelumnya untuk kiriman versi '+review.sourceVersion+'.</small>':'')+'<button type="button" class="dc-save-button g8-feedback-save" data-lesson="'+id+'" data-version="'+sub.version+'">Kirim feedback</button>':'')+'</details>';
 }
 function render(){const target=document.getElementById('g8EvidencePanel');if(!target||typeof dcTeacherState==='undefined'||dcTeacherState.grade!==8||dcTeacherState.quarter!==2)return;const id=dcTeacherState.studentId;if(!id)return;if(target.contains(document.activeElement))return;
  if(!loaded.has(id)){target.innerHTML='<p>Memuat kiriman Firebase…</p>';load(id).catch(e=>{target.innerHTML='<p>Kiriman belum termuat: '+esc(e.message)+'. Buka kembali siswa ini.</p>';});return;}
  const related=ids[dcTeacherState.selectedAssessmentId]||[],available=related.filter(key=>records[id]?.student?.lessons?.[key]),latest=[...available].reverse().find(key=>records[id].student.lessons[key].submission)||available[0];
  const previous=dcTeacherState.draft.evidenceSnapshots?.[dcTeacherState.selectedAssessmentId],newer=previous&&dcTeacherState.draft.evidenceVersions?.[dcTeacherState.selectedAssessmentId]!==version(id,dcTeacherState.selectedAssessmentId);
  target.innerHTML='<h4>Bukti dari Game Studio siswa</h4>'+(available.length?available.map(key=>card(id,key,key===latest)).join(''):'<p>Belum ada bukti untuk proyek ini. Setelah siswa masuk kembali dan mengirim dari Game Studio, tautan serta refleksinya tampil di sini.</p>')+([7,8].some(key=>records[id]?.student?.lessons?.[key])?'<details><summary>Bukti game pilihan / demo · pertemuan 7–8</summary>'+[7,8].map(key=>card(id,key)).join('')+'</details>':'')+(newer?'<details><summary>Bukti saat terakhir dinilai</summary>'+Object.entries(previous).map(([key,row])=>'<h5>Pertemuan '+key+' · v'+row.version+'</h5>'+proof(row)).join('')+'</details>':'');
  target.querySelectorAll('.g8-feedback-save').forEach(button=>{const key=button.dataset.lesson,remember=()=>{feedbackDrafts[id+'/'+key]={message:document.getElementById('g8-feedback-'+key).value,status:document.getElementById('g8-feedback-status-'+key).value};};document.getElementById('g8-feedback-'+key).addEventListener('input',remember);document.getElementById('g8-feedback-status-'+key).addEventListener('change',remember);button.addEventListener('click',async()=>{button.disabled=true;try{const teacher=await G8CloudIdentity.verifyTeacher();await db.ref('learningProgress').child(id).child('grade8Games/teacher/reviews').child(key).set({message:document.getElementById('g8-feedback-'+key).value,status:document.getElementById('g8-feedback-status-'+key).value,sourceVersion:Number(button.dataset.version),updatedAt:G8CloudIdentity.stamp(),updatedBy:teacher.uid});delete feedbackDrafts[id+'/'+key];showAlert('Feedback formatif kelas 8 terkirim. Nilai tetap disimpan melalui rubrik.','success');}catch(e){showAlert('Feedback belum terkirim: '+e.message,'danger');}finally{button.disabled=false;}});});
 }
 return {version,snapshot,render,refreshBeforeSave,invalidateStale,isStaleRecord,onProgress(data){for(const [id,row]of Object.entries(data||{})){if(row.grade8Games){records[id]=row.grade8Games;loaded.add(id);}}invalidateStale();render();}};
})();
